// Helper type
type TranslationKeys = typeof translations;
export type SectionKey = keyof TranslationKeys;
export type StringKey<S extends SectionKey> = keyof TranslationKeys[S];

// t() helper — used inside components
export function t<S extends SectionKey, K extends StringKey<S>>(
  section: S,
  key: K,
  lang: Language
): string {
  return (translations[section][key] as Record<Language, string>)[lang] ?? '';
}
